import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;StringTokenizer st1 = new StringTokenizer(line1);int n = Integer.parseInt(st1.nextToken());int k = Integer.parseInt(st1.nextToken());boolean[] seen = new boolean[1000001];boolean found = false;String line2 = br.readLine();if (line2 != null) {StringTokenizer st2 = new StringTokenizer(line2);for (int i = 0; i < n; i++) {int val = Integer.parseInt(st2.nextToken());if (val < k) {int target = k - val;if (target <= 1000000 && seen[target]) {found = true;break;}}if (val <= 1000000) {seen[val] = true;}}}if (found) {System.out.println("YES");} else {System.out.println("NO");}}}